/**
 * VaultSpark — Founder Presence Badge.
 *
 * Sitewide fixed pill in the bottom-left that lights up when the studio
 * owner is actively working. Data source: `/api/founder-presence.json`,
 * generated by `scripts/generate-founder-presence.mjs` from studio-ops
 * ACTIVE_SESSIONS.json.
 *
 * Respects voice/branding rules (no internal enums in user-facing copy —
 * label comes pre-rendered, sealed projects collapse to generic phrasing).
 * Honours prefers-reduced-motion + a user dismiss (session-scoped).
 *
 * Transport: Supabase Realtime broadcast channel `founder-presence` when
 * available (instant going-live / going-offline transitions). JSON poll is
 * the fallback + the canonical source of the label/project metadata.
 * Poll cadence drops from 90s → 5min once Realtime is connected.
 *
 * Publisher side (studio-ops repo) emits a broadcast whenever the active-
 * session digest changes. Until that ships, this client still works via
 * polling alone — the Realtime subscription is a no-op accelerant.
 * CSP-clean.
 */
(function () {
  'use strict';

  var ENDPOINT = '/api/founder-presence.json';
  var POLL_MS_FALLBACK = 90 * 1000;
  var POLL_MS_WHEN_REALTIME = 5 * 60 * 1000;
  var DISMISS_KEY = 'vs_presence_dismissed';
  var SUPPRESS_PATHS = ['/vault-member/', '/investor-portal/', '/studio-hub/', '/admin/'];
  var REALTIME_CHANNEL = 'founder-presence';

  function shouldSuppress() {
    var p = location.pathname;
    if (SUPPRESS_PATHS.some(function (s) { return p.indexOf(s) === 0; })) return true;
    try { return sessionStorage.getItem(DISMISS_KEY) === '1'; } catch (_) { return false; }
  }

  var STYLE = [
    '.vs-presence{position:fixed;left:1.1rem;bottom:1.1rem;z-index:50;display:none;align-items:center;gap:0.55rem;padding:0.55rem 0.9rem 0.55rem 0.75rem;border-radius:999px;background:rgba(13,16,28,0.92);border:1px solid rgba(255,196,0,0.35);color:var(--text,#e2e8f0);font-size:0.83rem;font-family:inherit;backdrop-filter:blur(8px);box-shadow:0 10px 28px rgba(0,0,0,0.4);max-width:calc(100vw - 2rem);}',
    '.vs-presence.vs-presence--live{display:inline-flex;}',
    '.vs-presence__dot{width:8px;height:8px;border-radius:50%;background:#FFC400;box-shadow:0 0 10px #FFC400;animation:vs-presence-pulse 2.2s ease-in-out infinite;flex-shrink:0;}',
    '@keyframes vs-presence-pulse{0%,100%{opacity:0.6;transform:scale(1);}50%{opacity:1;transform:scale(1.35);}}',
    '@media(prefers-reduced-motion:reduce){.vs-presence__dot{animation:none;}}',
    '.vs-presence__label{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}',
    '.vs-presence__close{margin-left:0.35rem;background:none;border:none;color:rgba(255,255,255,0.45);font-size:1rem;cursor:pointer;padding:0 0.2rem;line-height:1;}',
    '.vs-presence__close:hover{color:rgba(255,255,255,0.8);}',
    'body.light-mode .vs-presence{background:rgba(255,253,247,0.96);border-color:rgba(212,175,55,0.55);color:#141c34;}',
    'body.light-mode .vs-presence__close{color:rgba(20,28,52,0.5);}',
  ].join('\n');

  var host = null;

  function ensureHost() {
    if (host) return host;
    if (document.querySelector('style[data-vs-presence-style]')) return host;
    var s = document.createElement('style');
    s.setAttribute('data-vs-presence-style', '1');
    s.textContent = STYLE;
    document.head.appendChild(s);
    host = document.createElement('div');
    host.className = 'vs-presence';
    host.setAttribute('role', 'status');
    host.setAttribute('aria-live', 'polite');
    document.body.appendChild(host);
    return host;
  }

  function show(label) {
    ensureHost();
    host.innerHTML = '';
    var dot = document.createElement('span');
    dot.className = 'vs-presence__dot';
    var lbl = document.createElement('span');
    lbl.className = 'vs-presence__label';
    lbl.textContent = label;
    var close = document.createElement('button');
    close.type = 'button';
    close.className = 'vs-presence__close';
    close.setAttribute('aria-label', 'Dismiss presence badge');
    close.textContent = '×';
    close.addEventListener('click', function () {
      try { sessionStorage.setItem(DISMISS_KEY, '1'); } catch (_) {}
      host.classList.remove('vs-presence--live');
    });
    host.appendChild(dot); host.appendChild(lbl); host.appendChild(close);
    host.classList.add('vs-presence--live');
  }

  function hide() {
    if (host) host.classList.remove('vs-presence--live');
  }

  var realtimeConnected = false;

  function applyPayload(data) {
    if (data && data.live && data.label) show(data.label);
    else hide();
  }

  function tick() {
    if (shouldSuppress()) { hide(); return; }
    fetch(ENDPOINT, { credentials: 'omit', cache: 'no-store' })
      .then(function (r) { return r.ok ? r.json() : Promise.reject(new Error('presence_' + r.status)); })
      .then(applyPayload)
      .catch(function () { hide(); });
  }

  function subscribeRealtime(onPayload) {
    var sb = window.VSSupabase;
    if (!sb || typeof sb.channel !== 'function') return null;
    try {
      var ch = sb.channel(REALTIME_CHANNEL, { config: { broadcast: { self: false } } })
        .on('broadcast', { event: 'update' }, function (msg) {
          var payload = msg && msg.payload ? msg.payload : null;
          if (payload) onPayload(payload);
        })
        .subscribe(function (status) {
          realtimeConnected = (status === 'SUBSCRIBED');
        });
      return ch;
    } catch (_) {
      return null;
    }
  }

  function boot() {
    if (shouldSuppress()) return;
    var timer = null;
    var pollMs = POLL_MS_FALLBACK;
    var rtChannel = subscribeRealtime(applyPayload);
    if (rtChannel) pollMs = POLL_MS_WHEN_REALTIME;
    function start() { if (timer == null) { tick(); timer = setInterval(tick, pollMs); } }
    function stop()  { if (timer != null) { clearInterval(timer); timer = null; } }
    // Only poll while the tab is visible — saves battery + bandwidth when
    // a visitor has the tab backgrounded.
    document.addEventListener('visibilitychange', function () {
      if (document.hidden) stop(); else start();
    });
    if (!document.hidden) start();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else { boot(); }
})();
